package it.cavallium.rockserver.distributed.ratis;

import it.cavallium.rockserver.core.common.distributed.*;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.apache.ratis.client.RaftClient;
import org.apache.ratis.protocol.*;
import org.apache.ratis.thirdparty.com.google.protobuf.ByteString;

/** One immutable writable membership step. Durable unknown requests are never rebased onto another configuration. */
public final class RatisRelocationController implements AutoCloseable {
    public enum Phase { DEFINITION, BEGIN, JOINING, AUTHORIZE, REGISTER, TRANSFER, RELEASE, CONFIGURE, READY, PROOF, PUBLISH, COMPLETE, ACTIVE, CONFLICT }
    public record Anchor(RangeDescriptor range,ReplicaDescriptor owner){public Anchor{Objects.requireNonNull(range);Objects.requireNonNull(owner);if(!range.replicas().contains(owner))throw new IllegalArgumentException("Anchor owner missing");}}
    /** Trusted deployment/node registry, not supplied by serialized relocation requests. */
    @FunctionalInterface public interface Anchors { Anchor resolve(ReplicaDescriptor receiver)throws IOException; }
    private final Path root;private final RatisTopologyCatalogue catalogue;private final RatisSchemaAdministration schemas;private final RatisRangeImportCatalogue imports;private final RatisTopologyJoinAuthority.Client authority;private final RaftClient control;private final RatisNodePlan.Catalogue binding;private final RatisRelocationDataClient data;private final Anchors anchors;private final FileChannel lockChannel;private final FileLock lock;private final Map<UUID,Handle> handles=new HashMap<>();private boolean busy,closed;
    private final UUID cluster,database;
    private final Set<UUID> retained=new HashSet<>();
    public final class Handle {private final UUID id;private final Map<String,byte[]> fields;private boolean dirty;private Handle(UUID id,Map<String,byte[]> fields){this.id=id;this.fields=new HashMap<>(fields);}public UUID intentId(){return id;}public TopologyChange.Definition definition(){return TopologyChange.Definition.decode(fields.get("definition"));}public TopologyChange.State state(){return TopologyChange.State.decode(fields.get("state"));}public Phase phase(){return Phase.valueOf(new String(fields.get("phase"),StandardCharsets.US_ASCII));}}
    public RatisRelocationController(Path root,UUID cluster,UUID database,RatisNodePlan.Catalogue binding,RaftClient borrowed,RatisRelocationDataClient data,Anchors anchors)throws IOException{this.root=root.toAbsolutePath().normalize();if(!Files.isDirectory(this.root))throw new IOException("Relocation journal root absent");this.cluster=Objects.requireNonNull(cluster);this.database=Objects.requireNonNull(database);this.binding=Objects.requireNonNull(binding);control=Objects.requireNonNull(borrowed);this.data=Objects.requireNonNull(data);this.anchors=Objects.requireNonNull(anchors);catalogue=new RatisTopologyCatalogue(borrowed,cluster,database,binding.groupId(),binding.epoch(),binding.schemaDigest(),binding.directoryColumn());schemas=new RatisSchemaAdministration(borrowed,cluster,database,binding.groupId(),binding.epoch(),binding.schemaDigest(),binding.directoryColumn());imports=new RatisRangeImportCatalogue(borrowed,cluster,database,binding.groupId(),binding.epoch(),binding.schemaDigest(),binding.directoryColumn());authority=new RatisTopologyJoinAuthority.Client(borrowed,cluster,database,binding.groupId());lockChannel=FileChannel.open(this.root.resolve("relocation.lock"),StandardOpenOption.CREATE,StandardOpenOption.WRITE);try{lock=lockChannel.tryLock();if(lock==null)throw new IOException("Relocation root already owned");}catch(IOException|RuntimeException failed){lockChannel.close();throw failed;}try{try(var paths=Files.list(this.root)){for(var file:paths.filter(p->p.getFileName().toString().endsWith(".relocation")).toList()){var name=file.getFileName().toString();UUID id=UUID.fromString(name.substring(0,name.length()-11));if(!retained.add(id) || retained.size()>8)throw new IOException("Retained relocation journal bound exhausted");validate(new Handle(id,RatisSchemaClientJournal.read(file)));}}}catch(IOException|RuntimeException failed){lock.release();lockChannel.close();throw failed;}}
    public Handle prepare(TopologyChange.Definition definition)throws IOException{begin();try{if(definition.kind()!=TopologyChange.Kind.RELOCATE || !definition.header().clusterId().equals(cluster) || !definition.header().databaseId().equals(database) || retained.size()>=8 || Files.exists(path(definition.intentId())))throw new IOException("Relocation intent invalid/already retained");var fields=new HashMap<String,byte[]>();fields.put("binding",bindingBytes());fields.put("definition",definition.encode());fields.put("state",TopologyChange.State.begin(definition.header()).encode());fields.put("issuer",UUID.randomUUID().toString().getBytes(StandardCharsets.US_ASCII));fields.put("sequence",number(0));fields.put("phase",Phase.DEFINITION.name().getBytes(StandardCharsets.US_ASCII));var handle=new Handle(definition.intentId(),fields);retained.add(handle.id);save(handle);handles.put(handle.id,handle);return handle;}finally{end();}}
    public Handle reopen(UUID id)throws IOException{begin();try{if(handles.containsKey(id))return handles.get(id);if(!retained.contains(id) || handles.size()>=8)throw new IOException("Unknown/bounded retained relocation journal");var handle=new Handle(id,RatisSchemaClientJournal.read(path(id)));validate(handle);handles.put(id,handle);return handle;}finally{end();}}
    public Phase advance(Handle handle,int steps)throws IOException{begin();try{if(handles.get(handle.id)!=handle || steps<1 || steps>64)throw new IOException("Unknown relocation handle/step budget");if(handle.dirty)save(handle);for(int i=0;i<steps && handle.phase()!=Phase.ACTIVE;i++){if(handle.phase()==Phase.CONFLICT)throw new IOException("Frozen relocation command conflicted");if(handle.fields.containsKey("command")){execute(handle);continue;}step(handle);}return handle.phase();}finally{end();}}
    private void step(Handle h)throws IOException{var d=h.definition();var state=h.state();switch(h.phase()){
        case DEFINITION->command(h,catalogue.prepareDefinition(next(h),d,catalogue.readCapacity()),Phase.BEGIN);
        case BEGIN->{var previous=catalogue.readHead(d.header().domainId());var schema=schemas.readHead(d.header().domainId());var imported=imports.readHead(d.header().domainId());if(schema!=null)h.fields.put("schema",schema.encode());if(imported!=null)h.fields.put("import",imported.encode());command(h,catalogue.prepareBegin(next(h),d,previous,schema,imported),Phase.JOINING);}
        case JOINING->command(h,catalogue.prepareJoining(next(h),d,state,schema(h),imported(h)),Phase.AUTHORIZE);
        case AUTHORIZE->{if(!h.fields.containsKey("sourceCfg")){var evidence=data.read(new RatisRelocationOwnerRpc.Request(d,null,RatisRelocationOwnerRpc.Expected.SOURCE,null,null));h.fields.put("sourceCfg",evidence.configuration().data());h.fields.put("targetCfg",RatisRelocationDataClient.targetConfiguration(d.targets().getFirst(),evidence.configuration().data()));save(h);}if(!h.fields.containsKey("authorization")){var actor=d.parents().getFirst().replicas().stream().filter(r->r.role()==ReplicaDescriptor.Role.VOTER).findFirst().orElseThrow();var view=authority.read(RatisTopologyJoinAuthority.Request.of(d.header(),actor.replicaId(),RatisTopologyJoinAuthority.Purpose.SOURCE_CONFIGURATION));h.fields.put("authorization",new RatisTopologyRelocationRecord(RatisTopologyRelocationRecord.Action.AUTHORIZE,d,binding.groupId(),view.cut(),h.fields.get("sourceCfg"),h.fields.get("targetCfg")).encode());save(h);}data.append(RatisTopologyRelocationRecord.decode(h.fields.get("authorization")));move(h,Phase.REGISTER);}
        case REGISTER->{
            if(!h.fields.containsKey("imageHash")){
                var receiver=newReceiver(d);
                if(receiver!=null){var anchor=anchors.resolve(receiver);var registration=data.join(d,receiver,anchor.range(),anchor.owner());image(h,receiver,registration.imageCut(),registration.imageHash());}
                else {var promoted=promotedReceiver(d);if(promoted!=null){var source=data.read(new RatisRelocationOwnerRpc.Request(d,null,RatisRelocationOwnerRpc.Expected.SOURCE,null,null));boolean ready=false;try{ready=data.read(new RatisRelocationOwnerRpc.Request(d,promoted.replicaId(),RatisRelocationOwnerRpc.Expected.CAUGHT_UP,source.completedCut(),null)).caughtUp();}catch(IOException unavailable){/* The registered recovery endpoint independently qualifies its actual owner and catalogue. */}if(!ready){var prepared=data.recover(RatisNodeRuntime.sourceRequest(d,binding.groupId(),promoted),d);image(h,promoted,prepared.image().position(),prepared.image().sha256());}}}
            }move(h,Phase.TRANSFER);
        }
        case TRANSFER->{var receiver=imageReceiver(h);if(receiver!=null){var prepared=data.transfer(RatisNodeRuntime.sourceRequest(d,binding.groupId(),receiver),d);if(!Arrays.equals(prepared.image().sha256(),h.fields.get("imageHash")) || !prepared.image().position().equals(cut(h,"imageCut")))throw new IOException("Transfer changed original qualified image");}move(h,Phase.RELEASE);}
        case RELEASE->{var receiver=imageReceiver(h);if(receiver!=null)data.release(RatisNodeRuntime.sourceRequest(d,binding.groupId(),receiver),d);move(h,Phase.CONFIGURE);}
        case CONFIGURE->{try{var current=data.read(new RatisRelocationOwnerRpc.Request(d,null,RatisRelocationOwnerRpc.Expected.TARGET,null,null));if(RatisTopologyRelocationRecord.sameConfiguration(current.configuration().data(),h.fields.get("targetCfg")) && current.configuration().term()>0 && current.configuration().index()>0){move(h,Phase.READY);return;}}catch(IOException notTarget){/* The exact SOURCE→TARGET CAS remains the only permitted mutation. */}var source=data.read(new RatisRelocationOwnerRpc.Request(d,null,RatisRelocationOwnerRpc.Expected.SOURCE,null,null));if(!RatisTopologyRelocationRecord.sameConfiguration(source.configuration().data(),h.fields.get("sourceCfg")))throw new IOException("Frozen SOURCE configuration changed");for(var target:d.targets().getFirst().replicas())if(target.role()==ReplicaDescriptor.Role.VOTER && d.parents().getFirst().replicas().stream().anyMatch(old->old.replicaId().equals(target.replicaId()) && old.role()==ReplicaDescriptor.Role.LISTENER)){var ready=data.read(new RatisRelocationOwnerRpc.Request(d,target.replicaId(),RatisRelocationOwnerRpc.Expected.CAUGHT_UP,source.completedCut(),null));if(!ready.caughtUp())throw new IOException("Promotion waits for actual native listener catch-up");}save(h);data.compareAndSet(d,h.fields.get("sourceCfg"),h.fields.get("targetCfg"),authority);move(h,Phase.READY);}
        case READY->{var owner=data.read(new RatisRelocationOwnerRpc.Request(d,null,RatisRelocationOwnerRpc.Expected.TARGET,null,null));if(!RatisTopologyRelocationRecord.sameConfiguration(owner.configuration().data(),h.fields.get("targetCfg")) || owner.configuration().term()<1 || owner.configuration().index()<1)throw new IOException("Target configuration is not actually committed");for(var target:d.targets().getFirst().replicas())if(d.parents().getFirst().replicas().stream().noneMatch(old->old.replicaId().equals(target.replicaId())) || d.parents().getFirst().replicas().stream().anyMatch(old->old.replicaId().equals(target.replicaId()) && old.role()!=target.role())){if(imageReceiver(h)!=null && imageReceiver(h).replicaId().equals(target.replicaId())){var ready=data.read(new RatisRelocationOwnerRpc.Request(d,target.replicaId(),RatisRelocationOwnerRpc.Expected.IMAGE,cut(h,"imageCut"),h.fields.get("imageHash")));if(!ready.imageInstalled())throw new IOException("Target image has not imported");}var caught=data.read(new RatisRelocationOwnerRpc.Request(d,target.replicaId(),RatisRelocationOwnerRpc.Expected.TARGET,owner.completedCut(),null));if(!caught.caughtUp())throw new IOException("Target native configuration/tail not ready");}h.fields.put("targetCfg",owner.configuration().data());h.fields.put("proof",owner.proof(d.targets().getFirst().groupId(),owner.completedCut()).encode());save(h);move(h,Phase.PROOF);}
        case PROOF->command(h,catalogue.prepareReconfigured(next(h),d,state,TopologyChange.RelocationProof.decode(h.fields.get("proof")),schema(h),imported(h)),Phase.PUBLISH);
        case PUBLISH->command(h,catalogue.prepareRelocationPublication(next(h),d,state,schema(h),imported(h)),Phase.COMPLETE);
        case COMPLETE->{if(!h.fields.containsKey("completion")){var actor=d.targets().getFirst().replicas().stream().filter(r->r.role()==ReplicaDescriptor.Role.VOTER).findFirst().orElseThrow();var view=authority.read(RatisTopologyJoinAuthority.Request.of(d.header(),actor.replicaId(),RatisTopologyJoinAuthority.Purpose.PUBLICATION));h.fields.put("completion",new RatisTopologyRelocationRecord(RatisTopologyRelocationRecord.Action.COMPLETE,d,binding.groupId(),view.cut(),h.fields.get("sourceCfg"),h.fields.get("targetCfg")).encode());save(h);}data.append(RatisTopologyRelocationRecord.decode(h.fields.get("completion")));move(h,Phase.ACTIVE);}
        default->throw new IOException("Unexpected relocation phase");}}
    private void command(Handle h,DistributedCommand command,Phase next)throws IOException{h.fields.put("command",DistributedCommandCodec.encode(command));h.fields.put("next",next.name().getBytes(StandardCharsets.US_ASCII));save(h);}
    private void execute(Handle h)throws IOException{var command=DistributedCommandCodec.decode(h.fields.get("command"));if(RatisTopologyCatalogue.requiresOwnerAdmission(command)){var reply=RatisRoutedClient.rpc(()->control.io().sendReadOnly(Message.valueOf(ByteString.copyFrom(RatisTopologyExecutionRpc.prepareRequest(command)))));if(reply==null || !reply.isSuccess() || reply.getMessage()==null)throw new IOException("Relocation publication preparation failed");RatisTopologyExecutionRpc.requireEcho(reply.getMessage().getContent().toByteArray(),RatisTopologyExecutionRpc.PREPARE,command);}var result=catalogue.execute(command);if(result.status()!=CommandResult.Status.SUCCESS){move(h,Phase.CONFLICT);return;}if(command.mutations().getFirst().key().length==17){var next=TopologyChange.State.decode(command.mutations().getFirst().value());next.requireDefinition(h.definition());h.fields.put("state",next.encode());}var next=Phase.valueOf(new String(h.fields.get("next"),StandardCharsets.US_ASCII));h.fields.remove("command");h.fields.remove("next");move(h,next);}
    private void image(Handle h,ReplicaDescriptor receiver,ApplyPosition cut,byte[] hash)throws IOException{h.fields.put("imageReceiver",ByteBuffer.allocate(16).putLong(receiver.replicaId().getMostSignificantBits()).putLong(receiver.replicaId().getLeastSignificantBits()).array());h.fields.put("imageHash",hash);h.fields.put("imageCut",numberPair(cut));save(h);}
    private ReplicaDescriptor imageReceiver(Handle h)throws IOException{if(!h.fields.containsKey("imageHash"))return null;var encoded=ByteBuffer.wrap(h.fields.get("imageReceiver"));var id=new UUID(encoded.getLong(),encoded.getLong());return h.definition().targets().getFirst().replicas().stream().filter(r->r.replicaId().equals(id)).findFirst().orElseThrow(()->new IOException("Frozen image receiver changed"));}
    private static ReplicaDescriptor promotedReceiver(TopologyChange.Definition d){return d.targets().getFirst().replicas().stream().filter(r->r.role()==ReplicaDescriptor.Role.VOTER && d.parents().getFirst().replicas().stream().anyMatch(old->old.replicaId().equals(r.replicaId()) && old.role()==ReplicaDescriptor.Role.LISTENER)).findFirst().orElse(null);}
    private static ReplicaDescriptor newReceiver(TopologyChange.Definition d){return d.targets().getFirst().replicas().stream().filter(r->d.parents().getFirst().replicas().stream().noneMatch(old->old.replicaId().equals(r.replicaId()))).findFirst().orElse(null);}
    private OperationId next(Handle h){long value=ByteBuffer.wrap(h.fields.get("sequence")).getLong();h.fields.put("sequence",number(value+1));return new OperationId(UUID.fromString(new String(h.fields.get("issuer"),StandardCharsets.US_ASCII)),0,value);}
    private RatisSchemaAdministration.Head schema(Handle h){return h.fields.containsKey("schema")?RatisSchemaAdministration.Head.decode(h.fields.get("schema")):null;}private RatisRangeImportCatalogue.Head imported(Handle h){return h.fields.containsKey("import")?RatisRangeImportCatalogue.Head.decode(h.fields.get("import")):null;}
    private static byte[] number(long value){return ByteBuffer.allocate(8).putLong(value).array();}private static byte[] numberPair(ApplyPosition cut){return ByteBuffer.allocate(16).putLong(cut.term()).putLong(cut.index()).array();}private static ApplyPosition cut(Handle h,String key){var value=ByteBuffer.wrap(h.fields.get(key));return new ApplyPosition(value.getLong(),value.getLong());}
    private void move(Handle h,Phase phase)throws IOException{h.fields.put("phase",phase.name().getBytes(StandardCharsets.US_ASCII));save(h);}private Path path(UUID id){return root.resolve(id+".relocation");}private void save(Handle h)throws IOException{h.dirty=true;RatisSchemaClientJournal.write(path(h.id),h.fields);h.dirty=false;}
    private byte[] bindingBytes(){return ByteBuffer.allocate(120).putLong(cluster.getMostSignificantBits()).putLong(cluster.getLeastSignificantBits()).putLong(database.getMostSignificantBits()).putLong(database.getLeastSignificantBits()).putLong(binding.groupId().getMostSignificantBits()).putLong(binding.groupId().getLeastSignificantBits()).putLong(binding.epoch()).put(binding.schemaDigest()).putLong(binding.directoryColumn().getMostSignificantBits()).putLong(binding.directoryColumn().getLeastSignificantBits()).putLong(binding.sessionsColumn().getMostSignificantBits()).putLong(binding.sessionsColumn().getLeastSignificantBits()).array();}
    private void validate(Handle h)throws IOException{if(!Arrays.equals(bindingBytes(),h.fields.get("binding")) || !h.id.equals(h.definition().intentId()) || h.definition().kind()!=TopologyChange.Kind.RELOCATE || !h.definition().header().clusterId().equals(cluster) || !h.definition().header().databaseId().equals(database))throw new IOException("Relocation journal binding differs");h.state().requireDefinition(h.definition());h.phase();if(h.fields.get("sequence")==null || h.fields.get("sequence").length!=8 || ByteBuffer.wrap(h.fields.get("sequence")).getLong()<0)throw new IOException("Invalid relocation sequence");}

    private synchronized void begin()throws IOException{if(closed || busy)throw new IOException("Relocation controller unavailable");busy=true;}private synchronized void end(){busy=false;}
    @Override public synchronized void close()throws IOException{if(busy)throw new IOException("Actual relocation work active");if(closed)return;closed=true;lock.release();lockChannel.close();}
}
